import numpy as np
import time


def _R(L):
    # L: knot values of f*f including zeros at both ends
    s = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:])
    l1 = np.sum(np.diff(L))  # = sum of interior? no
    return s


def _score(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    l1 = np.sum(h) ** 2
    mx = np.max(L)
    if mx <= 0 or l1 <= 0:
        return 0.0
    return num / (l1 * mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best = np.ones(50, dtype=float)
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            best = s.copy()

    best_score = _score(best)

    # Try a smooth bump shape: the flat top gives a triangular autoconvolution;
    # a rounded bump tends to concentrate f*f more, raising R.
    # Use a raised-cosine / parabolic-like profile over a range of widths.
    N = 50
    for w in range(3, N + 1):
        x = np.linspace(-1.0, 1.0, w)
        # parabola-ish bump, non-negative
        h = np.clip(1.0 - x * x, 0.0, None)
        if np.sum(h) <= 0:
            continue
        sc = _score(h)
        if sc > best_score:
            best_score = sc
            best = h.copy()
        if time.process_time() > deadline:
            break

    # Try triangular ramps of various widths
    for w in range(2, N + 1):
        h = np.minimum(np.arange(w), np.arange(w)[::-1]) + 1.0
        sc = _score(h)
        if sc > best_score:
            best_score = sc
            best = h.copy()
        if time.process_time() > deadline:
            break

    # Try shapes with heavier tails: h ~ 1/sqrt(1+x^2) style
    for w in range(3, N + 1):
        x = np.linspace(-3.0, 3.0, w)
        h = 1.0 / (1.0 + x * x)
        sc = _score(h)
        if sc > best_score:
            best_score = sc
            best = h.copy()
        if time.process_time() > deadline:
            break

    return np.asarray(best, dtype=float)

