import numpy as np
import time


def _R_from_conv(conv, s, linf_hint=None):
    """R given the (already computed) autoconvolution array conv."""
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0 or s <= 0:
        return -1.0
    return l2sq / (s * s * linf)


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    return _R_from_conv(np.convolve(h, h), s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.72

    # Set up starting shape
    if start is not None:
        h = np.asarray(start, dtype=float).ravel().copy()
        h = np.maximum(h, 0.0)
        if h.size == 0 or h.sum() <= 0:
            h = None
    else:
        h = None

    if h is None:
        N = 4001
        x = np.linspace(-1.0, 1.0, N)
        h = np.clip(np.cos(0.5 * np.pi * x), 0.0, None) ** 0.5
        h = np.minimum(h, 1.0)

    N = h.size
    nfft = 1
    while nfft < 2 * N - 1:
        nfft <<= 1

    def rfft_conv(hh):
        return np.fft.irfft(np.fft.rfft(hh, nfft) ** 2, nfft)[:2 * N - 1]

    def score_fft(hh):
        s = hh.sum()
        if s <= 0:
            return -1.0
        return _R_from_conv(rfft_conv(hh), s)

    best_h = h.copy()
    best_r = score_fft(best_h)

    # Fast local coordinate ascent in "shape space".
    # Key trick: we exploit that f*f, ||f||_1, and ||f*f||_inf are smooth in h,
    # and use a small set of multiplicative + additive perturbations with a
    # shrinking step size schedule. We also do a "flat-region" pass, where
    # the profile is nearly constant (the top of the rounded box) and small
    # perturbations matter most there.
    def coord_ascent(h, budget_end, step_schedule):
        h = h.copy()
        cur_r = score_fft(h)
        Nl = h.size
        # Precompute indices ordered by a heuristic: corners first (they bend
        # the box), then bulk. We alternate passes over corners and bulk.
        for step in step_schedule:
            if time.process_time() > budget_end:
                return h, cur_r
            mx = h.max() if h.max() > 0 else 1.0
            improved = False
            # Pass 1: multiplicative
            for i in range(Nl):
                if time.process_time() > budget_end:
                    return h, cur_r
                hi = h[i]
                cands = [hi * (1.0 + step), hi * (1.0 - step),
                         hi * (1.0 + 2 * step), hi * (1.0 - 2 * step)]
                lb = cur_r
                lv = hi
                for v in cands:
                    if v < 0 or v == hi:
                        continue
                    h[i] = v
                    r = score_fft(h)
                    if r > lb:
                        lb = r
                        lv = v
                h[i] = lv
                if lb > cur_r:
                    cur_r = lb
                    improved = True
            if not improved:
                # Pass 2: additive with magnitude step*mx
                for i in range(Nl):
                    if time.process_time() > budget_end:
                        return h, cur_r
                    hi = h[i]
                    d1 = step * mx
                    cands = [hi + d1, hi - d1, hi + 2 * d1, hi - 2 * d1]
                    lb = cur_r
                    lv = hi
                    for v in cands:
                        if v < 0 or v == hi:
                            continue
                        h[i] = v
                        r = score_fft(h)
                        if r > lb:
                            lb = r
                            lv = v
                    h[i] = lv
                    if lb > cur_r:
                        cur_r = lb
                        improved = True
            if not improved:
                break
        return h, cur_r

    # Coarse-to-fine: first a downsampled version to find the profile, then
    # full resolution. Downsampling is crucial because full-res coordinate
    # ascent over 4001 points in 30s with FFT conv is too slow to converge.
    def downsample(hh, k):
        if k <= 1:
            return hh.copy()
        n = hh.size
        m = (n // k) * k
        if m < k:
            return hh.copy()
        return hh[:m].reshape(-1, k).mean(axis=1)

    def upsample(hh, n):
        x_old = np.linspace(0.0, 1.0, hh.size)
        x_new = np.linspace(0.0, 1.0, n)
        return np.maximum(np.interp(x_new, x_old, hh), 0.0)

    # Multi-resolution ladder
    ladder = [(100, [0.15, 0.08]), (200, [0.1, 0.05]),
              (400, [0.06, 0.03]), (800, [0.03, 0.015])]
    cur = best_h
    for k, steps in ladder:
        if time.process_time() > deadline:
            break
        nfft_local = nfft
        # work on downsampled
        if k < N:
            hd = downsample(cur, N // k if N // k >= 1 else 1)
        else:
            hd = cur.copy()
        # temporarily replace score function to use hd's nfft
        # (compute directly)
        def score_hd(hh):
            s = hh.sum()
            if s <= 0:
                return -1.0
            nf = 1
            while nf < 2 * hh.size - 1:
                nf <<= 1
            conv = np.fft.irfft(np.fft.rfft(hh, nf) ** 2, nf)[:2 * hh.size - 1]
            return _R_from_conv(conv, s)

        hd = hd.copy()
        cur_r_d = score_hd(hd)
        Nd = hd.size
        for step in steps:
            if time.process_time() > deadline:
                break
            mx = hd.max() if hd.max() > 0 else 1.0
            improved = False
            for i in range(Nd):
                if time.process_time() > deadline:
                    break
                hi = hd[i]
                cands = [hi * (1.0 + step), hi * (1.0 - step),
                         hi + step * mx, hi - step * mx]
                lb = cur_r_d
                lv = hi
                for v in cands:
                    if v < 0 or v == hi:
                        continue
                    hd[i] = v
                    r = score_hd(hd)
                    if r > lb:
                        lb = r
                        lv = v
                hd[i] = lv
                if lb > cur_r_d:
                    cur_r_d = lb
                    improved = True
            if not improved:
                break
        # upsample back to full N and rescore
        full = upsample(hd, N)
        r_full = score_fft(full)
        if r_full > best_r:
            best_h = full
            best_r = r_full
        cur = full
        if time.process_time() > deadline:
            break

    # Final full-resolution polish with small steps
    if time.process_time() < deadline:
        polished, pr = coord_ascent(best_h, deadline, [0.01, 0.004])
        if pr > best_r:
            best_h, best_r = polished, pr

    # Basin hopping: small structured perturbations
    rng = np.random.RandomState(2024)
    for _ in range(4):
        if time.process_time() > deadline:
            break
        h = best_h.copy()
        # perturb a contiguous window near the top
        k = max(2, N // 50)
        c = rng.randint(N)
        lo = max(0, c - k)
        hi = min(N, c + k)
        h[lo:hi] *= rng.uniform(0.85, 1.15, size=hi - lo)
        h = np.maximum(h, 0.0)
        r = score_fft(h)
        if r > best_r:
            best_h, best_r = h, r
        # try a descent
        if time.process_time() < deadline:
            h2, r2 = coord_ascent(best_h, deadline, [0.008, 0.003])
            if r2 > best_r:
                best_h, best_r = h2, r2

    if best_r <= 0:
        best_h = np.ones(N)
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def _fft(h, nfft):
    return np.fft.rfft(h, nfft)


def _conv_L_from_H(H, N, nfft):
    conv = np.fft.irfft(H * H, nfft)[:2 * N - 1]
    L = np.empty(conv.size + 2, dtype=float)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = conv
    return L


def _A_and_dA(L):
    a = L[:-1]
    b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    dA = np.zeros_like(L)
    dA[:-1] += (2.0 * a + b) / 3.0
    dA[1:] += (a + 2.0 * b) / 3.0
    return A, dA


def _grad_from_dL(h, dL, H, nfft, N, s, scale_s_term):
    dR_dconv = dL[1:-1]
    D = np.fft.rfft(dR_dconv, nfft)
    c = np.fft.irfft(D * np.conj(H), nfft)[:N]
    return 2.0 * c + scale_s_term


def _R_grad_exact(h):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    nfft = 1
    while nfft < 2 * N:
        nfft <<= 1
    H = _fft(h, nfft)
    L = _conv_L_from_H(H, N, nfft)
    A, dA = _A_and_dA(L)
    B = s * s
    j = int(np.argmax(L))
    M = L[j]
    if M <= 0:
        return -1e9, np.zeros_like(h)
    R = A / (B * M)
    dL = dA / (B * M)
    dL[j] -= A / (B * M * M)
    grad = _grad_from_dL(h, dL, H, nfft, N, s, -A / (B * B * M) * 2.0 * s)
    return R, grad


def _R_grad_smooth(h, p):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return -1e9, np.zeros_like(h)
    nfft = 1
    while nfft < 2 * N:
        nfft <<= 1
    H = _fft(h, nfft)
    L = _conv_L_from_H(H, N, nfft)
    A, dA = _A_and_dA(L)
    B = s * s
    Lp = np.maximum(L, 0.0)
    Sp = np.sum(Lp ** p) + 1e-12
    M = Sp ** (1.0 / p)
    if M <= 0:
        return -1e9, np.zeros_like(h)
    R = A / (B * M)
    dM_dL = (Lp ** (p - 1)) * (M ** (1 - p))
    dL = dA / (B * M) - A / (B * M * M) * dM_dL
    grad = _grad_from_dL(h, dL, H, nfft, N, s, -A / (B * B * M) * 2.0 * s)
    return R, grad


def _opt(h0, fg, maxiter, ftol=1e-15, gtol=1e-12):
    h0 = np.maximum(np.asarray(h0, dtype=float), 0.0)
    bounds = [(0.0, None)] * h0.size
    try:
        res = minimize(fg, h0, jac=True, method='L-BFGS-B', bounds=bounds,
                       options={'maxiter': maxiter, 'ftol': ftol, 'gtol': gtol})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h0


def _smooth_opt(h0, p, maxiter):
    def fg(x):
        r, g = _R_grad_smooth(x, p)
        return -r, -g
    return _opt(h0, fg, maxiter, ftol=1e-14, gtol=1e-10)


def _exact_opt(h0, maxiter):
    def fg(x):
        r, g = _R_grad_exact(x)
        return -r, -g
    return _opt(h0, fg, maxiter)


def _resample(h, N_target):
    if h.size == N_target:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, N_target)
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    end = t0 + budget_seconds * 0.80

    N_target = 8001
    best_h = None
    best_r = -1.0

    if start is not None:
        s_arr = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if s_arr.size and s_arr.sum() > 0:
            best_r = _R(s_arr)
            best_h = s_arr.copy()

    # Candidate working arrays to explore from
    seeds = []
    if best_h is not None:
        seeds.append(_resample(best_h, N_target))
    # A triangular fresh seed
    x = np.linspace(-1.0, 1.0, 4001)
    tri = np.maximum(1.0 - np.abs(x), 0.0)
    seeds.append(_resample(tri, N_target))

    for seed in seeds:
        if seed.sum() <= 0:
            continue
        h = seed / seed.max()
        r = _R(h)
        if r > best_r:
            best_r = r
            best_h = h.copy()

    if best_h is None:
        best_h = np.ones(N_target)
        best_r = _R(best_h)

    # Phase 1: smooth continuation from best, then exact polish
    h = best_h.copy()
    for p in (10, 30, 80, 200, 500, 1500):
        if time.process_time() > end:
            break
        h_try = _smooth_opt(h, p, 300)
        r_try = _R(h_try)
        if r_try > best_r:
            best_r = r_try
            best_h = h_try.copy()
        h = h_try

    if time.process_time() < end:
        h_try = _exact_opt(best_h, 800)
        r_try = _R(h_try)
        if r_try > best_r:
            best_r = r_try
            best_h = h_try.copy()

    # Phase 2: support trimming + exact reoptimization, with shrinking perturbations
    rng = np.random.default_rng(12345)
    base = best_h.copy()
    # Iteratively try various thresholds and noise levels
    attempts = [
        (0.0, 0.0), (0.001, 0.0), (0.003, 0.0), (0.008, 0.0),
        (0.0, 0.002), (0.002, 0.002), (0.005, 0.005),
    ]
    for frac_th, noise in attempts:
        if time.process_time() > end:
            break
        h_try = base.copy()
        if frac_th > 0:
            h_try[h_try < frac_th * h_try.max()] = 0.0
        if noise > 0:
            h_try = np.maximum(h_try * (1.0 + noise * rng.standard_normal(h_try.size)), 0.0)
        h_try = _exact_opt(h_try, 400)
        r_try = _R(h_try)
        if r_try > best_r:
            best_r = r_try
            best_h = h_try.copy()
            base = h_try.copy()

    # Phase 3: alternating exact-max polish (block coordinate style)
    for _ in range(40):
        if time.process_time() > end:
            break
        h_try = _exact_opt(best_h, 60)
        r_try = _R(h_try)
        if r_try > best_r + 1e-12:
            best_r = r_try
            best_h = h_try.copy()
        else:
            # tiny jitter to escape
            hj = best_h * (1.0 + 0.001 * rng.standard_normal(best_h.size))
            hj = np.maximum(hj, 0.0)
            h_try = _exact_opt(hj, 120)
            r_try = _R(h_try)
            if r_try > best_r:
                best_r = r_try
                best_h = h_try.copy()
            else:
                break

    if start is not None:
        s_arr = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if s_arr.size and _R(s_arr) > best_r:
            return s_arr

    return np.maximum(best_h, 0.0)
